-- Bloco 6/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (itens 46 a 49), qual é a diferença entre os médiuns psicógrafos mecânicos, semimecânicos e intuitivos?', 'No mecânico a mão move-se sem consciência do que escreve; no intuitivo o Espírito atua sobre o pensamento do médium; no semimecânico há impulso na mão acompanhado de consciência das palavras.', 'O mecânico usa máquinas de escrever; o intuitivo usa cestas; o semimecânico usa ardósias.', 'O mecânico só recebe Espíritos inferiores; o intuitivo só recebe Espíritos puros.', 'O mecânico escreve dormindo; o intuitivo escreve em transe cataléptico.', 'Não há distinção alguma entre os três modos de psicografia.', 'A', 'No médium mecânico o Espírito move diretamente a mão sem que o médium tenha consciência do escrito; no intuitivo transmite o pensamento; no semimecânico participam ambos os mecanismos.', 'O Que é o Espiritismo - Cap. II, itens 46 a 49', 'expert', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 41 a 44), como se caracterizam os médiuns de efeitos físicos, os audientes, os falantes e os videntes?', 'São graus hierárquicos de sacerdócio dentro das sociedades espíritas.', 'Pelos diferentes modos de percepção ou ação: produzem fenômenos materiais (ruídos, movimentos), ouvem os Espíritos, falam sob sua ação ou os veem em estado de vigília.', 'São faculdades exclusivas de pessoas que nasceram cegas ou surdas.', 'Referem-se apenas aos fenômenos de sonambulismo provocado por hipnose.', 'Designam médiuns que atuam somente uma vez na vida.', 'B', 'Kardec classifica as variedades de médiuns segundo os efeitos: efeitos físicos, sensitivos ou impressionáveis, audientes, falantes, videntes, sonâmbulos, curadores, pneumatógrafos e psicógrafos.', 'O Que é o Espiritismo - Cap. II, itens 41 a 44', 'facil', true),
  ('o_que_e_espiritismo', 'No Capítulo II (item 44), que nome específico Allan Kardec dá à faculdade raríssima de obter a escrita direta traçada pelos próprios Espíritos sem o uso da mão do médium?', 'Tiptologia alfabética.', 'Psicofonia consciente.', 'Pneumatografia (e pneumatofonia para os sons articulados no ar).', 'Clariaudiência intuitiva.', 'Bicorporeidade tangível.', 'C', 'Kardec denomina pneumatografia a escrita direta produzida pelos Espíritos sem intermediário manual, advertindo também contra as fraudes dos que simulam esse fenômeno.', 'O Que é o Espiritismo - Cap. II, item 44', 'dificil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (''Escolhos da mediunidade'', itens 55 a 64), qual é o maior perigo que ameaça os médiuns e pode levá-los à obsessão e à perda da assistência dos bons Espíritos?', 'O estudo constante das obras fundamentais da Codificação.', 'A prática gratuita da caridade em benefício dos enfermos.', 'O hábito de fazer preces antes das reuniões mediúnicas.', 'O orgulho, a presunção de infalibilidade e a fascinação exercida por Espíritos enganadores que lisonjeiam a vaidade do médium.', 'A leitura comparada das comunicações em grupos sérios.', 'D', 'O orgulho é a pedra de toque: quando o médium se julga privilegiado e infalível, afasta os bons Espíritos e entrega-se aos Espíritos mistificadores e fascinadores.', 'O Que é o Espiritismo - Cap. II, itens 55 a 64', 'expert', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo II (''Qualidades dos médiuns'', itens 65 a 71), o que atrai os bons Espíritos para junto de um médium?', 'A riqueza material e os títulos acadêmicos do médium.', 'A força física muscular e o temperamento sanguíneo.', 'O uso de talismãs, vestes especiais e incensos.', 'A cobrança de honorários elevados pelas sessões.', 'As qualidades morais do médium: bondade, benevolência, simplicidade de coração, humildade, devotamento e amor ao bem.', 'E', 'A faculdade mediúnica em si é orgânica e independe da moral, mas o seu bom uso e a assistência dos bons Espíritos dependem essencialmente das qualidades morais do médium.', 'O Que é o Espiritismo - Cap. II, itens 65 a 71', 'facil', true),
  ('o_que_e_espiritismo', 'No Capítulo II (''Charlatanismo'', itens 72 a 81), por que Allan Kardec afirma que o desinteresse material absoluto é a mais segura garantia contra o charlatanismo mediúnico?', 'Porque onde não há lucro nem especulação não há interesse em simular fenômenos, e os Espíritos Superiores não se prestam a exibições mercantis.', 'Porque os Espíritos cobram tributos espirituais em moedas antigas.', 'Porque a lei francesa proibia apenas as reuniões gratuitas.', 'Porque os médiuns gratuitos jamais precisam estudar a Doutrina.', 'Porque o dinheiro destrói quimicamente o fluido magnético humano.', 'A', 'Os Espíritos não estão à disposição de quem paga; um médium que explorasse sua faculdade precisaria simular fenômenos quando os Espíritos não quisessem comparecer, caindo na fraude.', 'O Que é o Espiritismo - Cap. II, itens 72 a 81', 'expert', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (''Identidade dos Espíritos'', itens 82 a 89), por que não devemos aceitar cegamente os grandes nomes venerados com que certos Espíritos assinam suas comunicações?', 'Porque nenhum Espírito elevado jamais se comunicou com a Terra.', 'Porque Espíritos mistificadores e orgulhosos frequentemente usurpam nomes respeitáveis para impor ideias absurdas ou apócrifas.', 'Porque os Espíritos esquecem todos os nomes próprios após a morte.', 'Porque apenas os Espíritos familiares possuem nome no mundo espiritual.', 'Porque a escrita mediúnica altera automaticamente as letras da assinatura.', 'B', 'A identidade dos Espíritos antigos ou ilustres não se prova pelo nome assinado, mas pela elevação constante das ideias, pureza moral, ausência de contradições e gravidade da linguagem.', 'O Que é o Espiritismo - Cap. II, itens 82 a 89', 'expert', true),
  ('o_que_e_espiritismo', 'No Capítulo II (''Contradições'', itens 90 a 97), qual é a causa principal das aparentes contradições encontradas em certas comunicações espíritas?', 'A variação climática entre os hemisférios norte e sul.', 'A instabilidade do fluido cósmico universal durante os eclipses.', 'A diversidade de graus de saber e moralidade entre os Espíritos comunicantes, pois cada um fala segundo seus conhecimentos e opiniões pessoais.', 'A falta de dicionários padronizados nas escolas europeias.', 'O defeito de fabricação dos lápis utilizados nas sessões.', 'C', 'Nem todos os Espíritos sabem tudo: os Espíritos inferiores ou pseudossábios emitem sistemas pessoais e opiniões divergentes, ao passo que os Espíritos Superiores estão sempre de acordo quanto ao ensino moral e fundamental.', 'O Que é o Espiritismo - Cap. II, itens 90 a 97', 'dificil', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 95 a 97), que método de controle Allan Kardec estabeleceu para distinguir a verdade do erro no ensino dos Espíritos?', 'Aceitar exclusivamente as comunicações de um único médium parisiense.', 'Submeter todas as mensagens à votação política das câmaras municipais.', 'Rejeitar qualquer comunicação que trate de filosofia ou moral.', 'O controle da razão aliado à concordância universal do ensino dado pelos Espíritos em diferentes lugares por múltiplos médiuns desconhecidos entre si.', 'Realizar sorteios semanais entre as mensagens psicografadas.', 'D', 'Kardec apoiou a Codificação na concordância geral do ensino dos Espíritos através de numerosos médiuns em diversos países e no exame rigoroso da lógica e do bom senso.', 'O Que é o Espiritismo - Cap. II, itens 95 a 97', 'dificil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo II (''Consequências do Espiritismo'', itens 98 a 104), qual é o critério pelo qual se reconhece o verdadeiro espírita?', 'Pela faculdade de mover objetos pesados sem contato físico.', 'Pelo número de livros espíritas que guarda em sua biblioteca.', 'Pelo uso de insígnias exteriores e fórmulas místicas de saudação.', 'Pela capacidade de adivinhar a sorte e o futuro das pessoas.', 'Pela sua transformação moral e pelos esforços que emprega para domar suas más inclinações, praticando a caridade por pensamentos, palavras e obras.', 'E', 'Crer apenas nos fenômenos faz o crente ou simpatizante; o verdadeiro espírita é o que aplica a moral da Doutrina para reformar-se intimamente e ser mais benevolente e caridoso.', 'O Que é o Espiritismo - Cap. II, itens 98 a 104', 'facil', true);
ON CONFLICT (statement) DO NOTHING;

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';